Here's a complete TCP/IP server implementation in C with error handling and comments:

## Basic TCP Server

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <errno.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CLIENTS 5

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE] = {0};

    // Step 1: Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        return 1;
    }
    printf("Socket created successfully\n");

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        return 1;
    }

    // Step 2: Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;  // Accept connections from any IP
    server_addr.sin_port = htons(PORT);

    // Step 3: Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        return 1;
    }
    printf("Socket bound to port %d\n", PORT);

    // Step 4: Listen for connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        close(server_fd);
        return 1;
    }
    printf("Server listening on port %d...\n", PORT);

    // Step 5: Accept and handle connections
    while (1) {
        printf("\nWaiting for connections...\n");

        // Accept a client connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        // Get client information
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(client_addr.sin_addr), client_ip, INET_ADDRSTRLEN);
        printf("Client connected from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        // Handle client communication
        while (1) {
            memset(buffer, 0, BUFFER_SIZE);

            // Receive data from client
            int bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

            if (bytes_received < 0) {
                perror("Receive failed");
                break;
            } else if (bytes_received == 0) {
                printf("Client disconnected\n");
                break;
            }

            printf("Received: %s", buffer);

            // Check for exit command
            if (strcmp(buffer, "exit\n") == 0) {
                printf("Client requested to close connection\n");
                break;
            }

            // Echo back to client
            char response[BUFFER_SIZE];
            snprintf(response, BUFFER_SIZE, "Server received: %s", buffer);

            if (send(client_fd, response, strlen(response), 0) < 0) {
                perror("Send failed");
                break;
            }
        }

        // Close client connection
        close(client_fd);
        printf("Client connection closed\n");
    }

    // Clean up (This code is unreachable in this example)
    close(server_fd);
    return 0;
}
```

## Concurrent Server with Threads (Multi-client)

Here's an enhanced version that can handle multiple clients simultaneously:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <pthread.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CLIENTS 10

typedef struct {
    int socket;
    struct sockaddr_in address;
} client_t;

void *handle_client(void *args) {
    client_t *client = (client_t *)arg;
    char buffer[BUFFER_SIZE] = {0};

    char client_ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &(client->address.sin_addr), client_ip, INET_ADDRSTRLEN);

    printf("[Thread %ld] Handling client %s:%d\n", pthread_self(), client_ip, 
           ntohs(client->address.sin_port));

    while (1) {
        memset(buffer, 0, BUFFER_SIZE);
        int bytes = recv(client->socket, buffer, BUFFER_SIZE - 1, 0);

        if (bytes <= 0) {
            if (bytes == 0)
                printf("[Thread %ld] Client disconnected\n", pthread_self());
            else
                perror("recv error");
            break;
        }

        printf("[Thread %ld] Received: %s", pthread_self(), buffer);

        // Send response
        char response[BUFFER_SIZE];
        snprintf(response, BUFFER_SIZE, "Echo: %s", buffer);
        send(client->socket, response, strlen(response), 0);
        }

    close(client->socket);
    free(client);
    pthread_exit(NULL);
}

int main() {
    int server_fd;
    struct sockaddr_in server_addr;

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        return 1;
    }

    // Set socket options
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    // Configure address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        return 1;
    }

    // Listen
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        close(server_fd);
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept connections
    while (1) {
        client_t *new_client = malloc(sizeof(client_t));
        socklen_t client_len = sizeof(new_client->address);

        new_client->socket = accept(server_fd, (struct sockaddr *)&new_client->address, 
                                     &client_addr_len);

        if (new_client->socket < 0) {
            perror("Accept failed");
            free(new_client);
            continue;
        }

        // Create thread for new client
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, handle_client, (void *)new_client) != 0) {
            perror("Could not create thread");
            close(new_client->socket);
            free(new_client);
            continue;
        }

        // Detach thread to reclaim resources when it terminates
        pthread_detach(thread_id);
    }

    close(server_fd);
    return 0;
}
```

## Compilation and Usage

### For basic server:
```bash
gcc tcp_server.c -o tcp_server
./tcp_server
```

### For multi-threaded server:
```bash
gcc tcp_server_threaded.c -o tcp_server -lpthread
./tcp_server
```

### Testing with telnet or netcat:
```bash
# Using telnet
telnet localhost 8080

# Using netcat
nc localhost 8080
```

## Key Features:

1. **Error Handling**: Proper error checking for all system calls
2. **Socket Options**: SO_REUSEADDR to quickly restart server
3. **Buffer Management**: Clear buffers before use to prevent data corruption
4. **Client Information**: Displays connected client IP and port
5. **Graceful Shutdown**: Properly closes connections and handles client disconnections
6. **Thread Support**: Multi-client version handles multiple concurrent connections

## Common Improvements:

- Add signal handling to properly shutdown server gracefully
- implement timeouts for client operations
- Add logging functionality
- Implement message protocol or authentication
- Use `select()/`poll()`/asynchronous I/O instead of multithreading

Remember to handle firewall rules if testing across network!

